PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS supporter_status (character_id TEXT PRIMARY KEY REFERENCES characters(id),broadcaster_id TEXT NOT NULL,tier INTEGER NOT NULL CHECK(tier BETWEEN 0 AND 3),gifted INTEGER NOT NULL CHECK(gifted IN(0,1)),verified_at INTEGER NOT NULL,source TEXT NOT NULL CHECK(source IN('simulation','twitch')));
CREATE TABLE IF NOT EXISTS kingdom_growth (kingdom TEXT PRIMARY KEY REFERENCES kingdoms(id),high_water INTEGER NOT NULL CHECK(high_water>=0));
CREATE TABLE IF NOT EXISTS challenges (id TEXT PRIMARY KEY,template TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open',winner_id TEXT,opened_at INTEGER NOT NULL,expires_at INTEGER NOT NULL,completed_at INTEGER);
CREATE TABLE IF NOT EXISTS challenge_progress (challenge_id TEXT NOT NULL REFERENCES challenges(id),entity_id TEXT NOT NULL,score INTEGER NOT NULL,PRIMARY KEY(challenge_id,entity_id));
CREATE TABLE IF NOT EXISTS challenge_contributions (challenge_id TEXT NOT NULL REFERENCES challenges(id),character_id TEXT NOT NULL REFERENCES characters(id),milestone_key TEXT NOT NULL,kingdom TEXT NOT NULL REFERENCES kingdoms(id),PRIMARY KEY(challenge_id,character_id,milestone_key));
CREATE TABLE IF NOT EXISTS environment (id INTEGER PRIMARY KEY CHECK(id=1),mode TEXT NOT NULL CHECK(mode IN ('live','simulation')),generation TEXT NOT NULL,version INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY,subject TEXT UNIQUE NOT NULL,name TEXT NOT NULL,synthetic INTEGER NOT NULL CHECK(synthetic IN(0,1)));
CREATE TABLE IF NOT EXISTS kingdoms (id TEXT PRIMARY KEY CHECK(id IN('north','east','west')),points INTEGER NOT NULL DEFAULT 0,wins INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS seasons (id TEXT PRIMARY KEY,number INTEGER UNIQUE NOT NULL,starts_at INTEGER NOT NULL,ends_at INTEGER NOT NULL,status TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS characters (id TEXT PRIMARY KEY,user_id TEXT UNIQUE NOT NULL REFERENCES users(id),kingdom TEXT NOT NULL REFERENCES kingdoms(id),class TEXT NOT NULL CHECK(class IN('vanguard','ranger','rogue')),xp INTEGER NOT NULL CHECK(xp>=0),gold INTEGER NOT NULL CHECK(gold>=0),contribution INTEGER NOT NULL DEFAULT 0,wins INTEGER NOT NULL DEFAULT 0,joined_at INTEGER NOT NULL,last_active INTEGER NOT NULL,last_switch INTEGER NOT NULL DEFAULT 0,class_session TEXT,version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS inventory (id TEXT PRIMARY KEY,character_id TEXT NOT NULL REFERENCES characters(id),definition TEXT NOT NULL,upgrade INTEGER NOT NULL CHECK(upgrade BETWEEN 0 AND 5),equipped INTEGER NOT NULL CHECK(equipped IN(0,1)),UNIQUE(character_id,definition));
CREATE TABLE IF NOT EXISTS territories (id TEXT PRIMARY KEY,owner TEXT NOT NULL REFERENCES kingdoms(id),last_session TEXT);
CREATE TABLE IF NOT EXISTS ledger (id INTEGER PRIMARY KEY AUTOINCREMENT,character_id TEXT NOT NULL REFERENCES characters(id),delta INTEGER NOT NULL,balance_after INTEGER NOT NULL CHECK(balance_after>=0),reason TEXT NOT NULL,source_id TEXT NOT NULL,created_at INTEGER NOT NULL,UNIQUE(character_id,reason,source_id));
CREATE TABLE IF NOT EXISTS rewards (character_id TEXT NOT NULL REFERENCES characters(id),source_id TEXT NOT NULL,kind TEXT NOT NULL,session TEXT NOT NULL,xp INTEGER NOT NULL,gold INTEGER NOT NULL,PRIMARY KEY(character_id,source_id,kind));
CREATE TABLE IF NOT EXISTS receipts (key TEXT PRIMARY KEY,result TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS events (id INTEGER PRIMARY KEY AUTOINCREMENT,type TEXT NOT NULL,title TEXT NOT NULL,body TEXT NOT NULL,source TEXT NOT NULL,kingdom TEXT,created_at INTEGER NOT NULL,narrative_source TEXT NOT NULL DEFAULT 'template');
CREATE TABLE IF NOT EXISTS chapters (id TEXT PRIMARY KEY,attacker TEXT NOT NULL REFERENCES kingdoms(id),defender TEXT NOT NULL REFERENCES kingdoms(id),territory TEXT NOT NULL REFERENCES territories(id),status TEXT NOT NULL CHECK(status IN('open','paused','resolved','cancelled')),deadline INTEGER NOT NULL,remaining INTEGER,seed INTEGER NOT NULL,created_at INTEGER NOT NULL,resolved_at INTEGER,input TEXT,result TEXT);
CREATE UNIQUE INDEX IF NOT EXISTS one_active_chapter ON chapters((1)) WHERE status IN('open','paused');
CREATE TABLE IF NOT EXISTS participants (chapter_id TEXT NOT NULL REFERENCES chapters(id),character_id TEXT NOT NULL REFERENCES characters(id),kingdom TEXT NOT NULL REFERENCES kingdoms(id),created_at INTEGER NOT NULL,PRIMARY KEY(chapter_id,character_id));
CREATE TABLE IF NOT EXISTS votes (chapter_id TEXT NOT NULL,character_id TEXT NOT NULL,tactic TEXT NOT NULL CHECK(tactic IN('attack','defend','raid')),created_at INTEGER NOT NULL,PRIMARY KEY(chapter_id,character_id),FOREIGN KEY(chapter_id,character_id) REFERENCES participants(chapter_id,character_id));
CREATE TABLE IF NOT EXISTS elections (id TEXT PRIMARY KEY,kingdom TEXT NOT NULL REFERENCES kingdoms(id),status TEXT NOT NULL CHECK(status IN('nominating','voting','closed')),nomination_end INTEGER NOT NULL,deadline INTEGER NOT NULL,winner TEXT REFERENCES characters(id),reason TEXT,created_at INTEGER NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS one_election_per_kingdom ON elections(kingdom) WHERE status IN('nominating','voting');
CREATE TABLE IF NOT EXISTS eligibility (election_id TEXT NOT NULL REFERENCES elections(id),character_id TEXT NOT NULL REFERENCES characters(id),PRIMARY KEY(election_id,character_id));
CREATE TABLE IF NOT EXISTS candidates (election_id TEXT NOT NULL,character_id TEXT NOT NULL,PRIMARY KEY(election_id,character_id),FOREIGN KEY(election_id,character_id) REFERENCES eligibility(election_id,character_id));
CREATE TABLE IF NOT EXISTS ballots (election_id TEXT NOT NULL,voter TEXT NOT NULL,candidate TEXT NOT NULL,PRIMARY KEY(election_id,voter),FOREIGN KEY(election_id,voter) REFERENCES eligibility(election_id,character_id),FOREIGN KEY(election_id,candidate) REFERENCES candidates(election_id,character_id));
CREATE TABLE IF NOT EXISTS lords (id TEXT PRIMARY KEY,kingdom TEXT NOT NULL REFERENCES kingdoms(id),character_id TEXT NOT NULL REFERENCES characters(id),starts_at INTEGER NOT NULL,ends_at INTEGER NOT NULL,reason TEXT);
CREATE TABLE IF NOT EXISTS season_awards (season_id TEXT NOT NULL REFERENCES seasons(id),kind TEXT NOT NULL,subject TEXT NOT NULL,score INTEGER NOT NULL,rank INTEGER NOT NULL,PRIMARY KEY(season_id,kind,subject));
CREATE TABLE IF NOT EXISTS overlay_keys (hash TEXT PRIMARY KEY,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS narrative_jobs (event_id INTEGER PRIMARY KEY REFERENCES events(id),status TEXT NOT NULL DEFAULT 'pending',attempts INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS outbox (id INTEGER PRIMARY KEY AUTOINCREMENT,event_id INTEGER NOT NULL REFERENCES events(id),body TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',created_at INTEGER NOT NULL,UNIQUE(event_id));
CREATE INDEX IF NOT EXISTS characters_faction ON characters(kingdom,contribution DESC,id);
CREATE INDEX IF NOT EXISTS pending_narratives ON narrative_jobs(status,event_id);
CREATE INDEX IF NOT EXISTS events_recent ON events(created_at DESC);
CREATE INDEX IF NOT EXISTS chapter_history ON chapters(created_at DESC);
